SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, region, CASE WHEN sqft >= 17000 THEN 'high' WHEN sqft >= 6724 THEN 'mid' ELSE 'low' END AS sqft_bucket, COUNT(*) AS total_count, SUM(CASE WHEN region = 'West' THEN sqft ELSE 0 END) AS west_sqft, COUNT(DISTINCT sqft) AS unique_regions FROM stores GROUP BY 1, 2, 3 HAVING COUNT(DISTINCT sqft) > 1 ORDER BY unique_regions;
